/**
 * @name Command injection via subprocess
 * @description Detects potential command injection through subprocess calls with shell=True or unsanitized input
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection-subprocess
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts
import semmle.python.ApiGraphs

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Any external input could be a source
    source instanceof DataFlow::ParameterNode or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("os").getMember("environ").getMember("get").getACall() and
      source = call
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(SystemCommandExecution cmd |
      sink = cmd.getCommand()
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential command injection from $@.", source.getNode(), "user input"

/**
 * @name Path traversal vulnerability
 * @description User-controlled file paths may allow access to unintended files
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
    or
    // Function parameters that could be user-controlled
    exists(DataFlow::ParameterNode param |
      source = param and
      not param.getParameter().getName() in ["self", "cls"]
    )
  }

  predicate isSink(DataFlow::Node sink) {
    sink = any(FileSystemAccess fa).getAPathArgument()
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential path traversal from $@.", source.getNode(), "user input"

/**
 * @name Insecure deserialization
 * @description Deserializing untrusted data may allow an attacker to execute arbitrary code
 * @kind path-problem
 * @problem.severity error
 * @id py/insecure-deserialization
 * @tags security
 *       external/cwe/cwe-502
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs
import semmle.python.dataflow.new.RemoteFlowSources

module InsecureDeserializationConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      // pickle.loads, pickle.load
      call = API::moduleImport("pickle").getMember(["loads", "load"]).getACall() and
      sink = call.getArg(0)
      or
      // marshal.loads, marshal.load
      call = API::moduleImport("marshal").getMember(["loads", "load"]).getACall() and
      sink = call.getArg(0)
      or
      // shelve.open
      call = API::moduleImport("shelve").getMember("open").getACall() and
      sink = call.getArg(0)
      or
      // yaml.load without safe loader
      call = API::moduleImport("yaml").getMember("load").getACall() and
      sink = call.getArg(0)
    )
  }
}

module InsecureDeserializationFlow = TaintTracking::Global<InsecureDeserializationConfig>;

import InsecureDeserializationFlow::PathGraph

from InsecureDeserializationFlow::PathNode source, InsecureDeserializationFlow::PathNode sink
where InsecureDeserializationFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Insecure deserialization from $@.", source.getNode(), "user input"
